#!/bin/sh
set -eu
script_dir=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
awk -F, '
NR == 1 { next }
{
  totals[$1] += $2
}
END {
  for (name in totals) {
    print name "\t" totals[name]
  }
}
' "$script_dir/source.csv" | LC_ALL=C sort > "$script_dir/totals.tsv"
EOF
chmod +x /app/build-totals.sh
